            turkishMeaning = "Allah'ım! Sen benim Rabbimsin, Senden başka ilah yoktur. Beni Sen yarattın ve ben Senin kulunum. Gücüm yettiğince Senin ahdin ve vaadin üzereyim. Yaptığım kötülüklerin şerrinden Sana sığınırım. Üzerimdeki nimetini itiraf eder, günahımı da ikrar ederim. Beni bağışla; çünkü günahları Senden başka bağışlayacak hiç kimse yoktur.",
            englishMeaning = "O Allah, You are my Lord, there is no deity but You. You created me and I am Your servant, and I abide by Your covenant and promise as best I can. I seek refuge in You from the evil of what I have done. I acknowledge Your favor upon me and I confess my sin, so forgive me, for surely none forgives sins except You.",
            benefits = "Peygamber Efendimiz (s.a.v.) sabah ve akşam inanarak bu duayı okuyanın cennet اهli olacağını müjdelemiştir.",
            englishBenefits = "Prophet Muhammad (peace be upon him) promised Paradise to whoever recites this with sincere faith in the morning and evening.",
            arabicBenefits = "بشّر النبي ﷺ من قالها موقناً بها حين يمسي وحين يصبح بأنه من أهل الجنة.",
            audioUrl = null
        ),
        PrayerSurah(
            id = "ezan_duasi",
            title = "Ezan Duâsı (Vesîle Duâsı)",
            englishTitle = "Supplication After Adhan",
            arabicTitle = "دُعَاءُ بَعْدَ الْأَذَانِ",
            category = SurahCategory.DUALAR,
            whereRecited = "Ezan-ı Muhammedi tamamlandığında Peygamber Efendimiz'in şefaatine nail olmak için okunur.",
            englishWhereRecited = "Recited immediately after the Adhan finishes to attain the intercession of the Prophet (peace be upon him).",
            arabicWhereRecited = "يُقرأ عقب انتهاء الأذان لنيل شفاعة النبي ﷺ يوم القيامة.",
            arabicText = "اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ",
            turkishPronunciation = "Allâhümme rabbe hâzihid-da'vetit-tâmmeti ves-salâtil-kâimeti âti Muhammedenil-vesîlete vel-fadîlete veb'ashü makâmen mahmûdenillezî veadteh.",
            turkishMeaning = "Ey bu eksiksiz davetin ve kılınacak namazın Rabbi olan Allah'ım! Hz. Muhammed'e vesîleyi ve fazileti ver. Onu, kendisine vaat ettiğin Makâm-ı Mahmûd'a ulaştır.",
            englishMeaning = "O Allah, Lord of this perfect call and established prayer! Grant Muhammad the intercession and favor, and raise him to the praised station which You have promised him.",
            benefits = "Kim ezanı işittiğinde bu duayı okursa Kıyamet gününde Peygamberimizin şefaati ona helal olur.",
            englishBenefits = "Whoever recites this after hearing the Adhan becomes worthy of the Prophet's intercession on the Day of Judgment.",
            arabicBenefits = "من قالها حين يسمع النداء حلّت له شفاعة النبي ﷺ يوم القيامة.",
            audioUrl = null
        ),
        PrayerSurah(
            id = "inshirah_sifa_duasi",
