        PrayerSurah(
            id = "fatiha",
            title = "Fâtiha Suresi",
            englishTitle = "Surah Al-Fatiha",
            arabicTitle = "سُورَةُ الفَاتِحَة",
            category = SurahCategory.SURELER,
            whereRecited = "Namazın her rekatında kıyamda okunması vaciptir / farzdır. Namazın temel direğidir.",
            englishWhereRecited = "Recited while standing in every rak'ah of every prayer; the essential pillar of Salah.",
            arabicWhereRecited = "تُقرأ في كل ركعة من ركعات الصلاة وهي ركن من أركان الصلاة.",
            arabicText = "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ۝ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝ الرَّحْمَنِ الرَّحِيمِ ۝ مَالِكِ يَوْمِ الدِّينِ ۝ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ۝ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ۝ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ",
            turkishPronunciation = "Bismillâhir-rahmânir-rahîm. Elhamdü lillâhi rabbil-âlemîn. Er-rahmânir-rahîm. Mâliki yevmid-dîn. İyyâke na'büdü ve iyyâke nesteîn. İhdinas-sırâtal-müstekîm. Sırâtallezîne en'amte aleyhim, ğayril-mağdûbi aleyhim veled-dâllîn.",
            turkishMeaning = "Rahmân ve Rahîm olan Allah'ın adıyla. Hamd, âlemlerin Rabbi olan Allah'a aittir. O Rahmândır, Rahîmdir. Din (hesap) gününün sahibidir. Yalnız Sana kulluk eder ve yalnız Senden yardım dileriz. Bizi doğru yola ilet; kendilerine nimet verdiğin kimselerin yoluna, gazaba uğrayanların ve sapanların yoluna değil.",
            englishMeaning = "In the name of Allah, the Entirely Merciful, the Especially Merciful. All praise is due to Allah, Lord of the worlds—The Entirely Merciful, the Especially Merciful, Sovereign of the Day of Recompense. It is You we worship and You we ask for help. Guide us to the straight path—the path of those upon whom You have bestowed favor, not of those who have evoked anger or of those who are astray.",
            benefits = "Kur'an'ın anası (Ümmü'l-Kitap) ve şifa kaynağıdır; Fâtiha'sız namaz olmaz.",
            englishBenefits = "Known as Umm al-Kitab (Mother of the Book) and Ash-Shifa (The Cure); no prayer is complete without it.",
            arabicBenefits = "أمّ الكتاب والسبع المثاني والشفاء التام؛ لا صلاة لمن لم يقرأ بفاتحة الكتاب.",
            audioUrl = "https://everyayah.com/data/Alafasy_128kbps/001001.mp3"
        ),
        PrayerSurah(
            id = "fil",
            title = "Fîl Suresi",
            englishTitle = "Surah Al-Fil",
            arabicTitle = "سُورَةُ الفِيل",
            category = SurahCategory.SURELER,
            whereRecited = "Namaz rekatlarında Fâtiha'dan sonra zamm-ı sure olarak okunur.",
            englishWhereRecited = "Recited after Surah Al-Fatiha in prayer rak'ahs.",
            arabicWhereRecited = "تُقرأ بعد سورة الفاتحة في ركعات الصلاة.",
            arabicText = "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ ۝ أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ ۝ وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ ۝ تَرْمِيهِمْ بِحِجَارَةٍ مِنْ سِجِّيلٍ ۝ فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ",
            turkishPronunciation = "Elem tera keyfe fe'ale rabbüke bi-ashâbil-fîl. Elem yec'al keydehüm fî tadlîl. Ve ersele aleyhim tayran ebâbîl. Termîhim bi-hıcâratin min siccîl. Fece'alehüm ke'asfin me'kûl.",
            turkishMeaning = "Görmedin mi Rabbin fil sahiplerine ne yaptı? Onların tuzaklarını boşa çıkarmadı mı? Üzerlerine sürü sürü Ebâbîl kuşları gönderdi. Onlara pişkin tuğladan taşlar atıyorlardı. Sonunda onları yenilmiş ekin yaprağı gibi yaptı.",
            englishMeaning = "Have you not considered how your Lord dealt with the companions of the elephant? Did He not make their plan into misguidance? And He sent against them birds in flocks, striking them with stones of hard clay, and He made them like eaten straw.",
            benefits = "Kâbe'yi koruyan Allah'ın kudretini ve zorbaların helakını hatırlatır.",
            englishBenefits = "Reminds believers of Allah's supreme power in protecting the Kaaba from tyranny.",
            arabicBenefits = "تذكّر بقدرة الله عز وجل في حماية الكعبة المشرفة وإهلاك الظالمين.",
            audioUrl = "https://everyayah.com/data/Alafasy_128kbps/105001.mp3"
        ),
        PrayerSurah(
            id = "kureys",
            title = "Kureyş Suresi",
            englishTitle = "Surah Quraysh",
            arabicTitle = "سُورَةُ قُرَيْش",
            category = SurahCategory.SURELER,
            whereRecited = "Namaz rekatlarında Fâtiha'dan sonra zamm-ı sure olarak okunur.",
            englishWhereRecited = "Recited after Surah Al-Fatiha in prayer rak'ahs.",
            arabicWhereRecited = "تُقرأ بعد سورة الفاتحة في ركعات الصلاة.",
            arabicText = "لِإِيلَافِ قُرَيْشٍ ۝ إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ ۝ فَلْيَعْبُدُوا رَبَّ هَذَا الْبَيْتِ ۝ الَّذِي أَطْعَمَهُمْ مِنْ جُوعٍ وَآمَنَهُمْ مِنْ خَوْفٍ",
            turkishPronunciation = "Li-îlâfi Kureyş. Îlâfihim rıhleteş-şitâi ves-sayf. Felya'büdû rabbe hâzel-beyt. Ellezî et'amehüm min cû'in ve âmenehüm min havf.",
            turkishMeaning = "Kureyş'in güven ve uzlaşmasını sağladığı için; kış ve yaz yolculuklarında onları güvenli kıldığı için... Artık bu evin (Kâbe'nin) Rabbine ibadet etsinler. O ki, onları açlıktan doyurdu ve korkudan emin kıldı.",
            englishMeaning = "For the accustomed security of the Quraysh—their accustomed security in the caravan of winter and summer—let them worship the Lord of this House, Who has fed them, saving them from hunger, and made them safe, saving them from fear.",
            benefits = "Şükrü, rızık ve güven nimetini hatırlatır.",
            englishBenefits = "Calls for gratitude to Allah for the blessings of sustenance and safety.",
            arabicBenefits = "تدعو إلى شكر الله على نعمتي الرزق والأمن.",
            audioUrl = "https://everyayah.com/data/Alafasy_128kbps/106001.mp3"
        ),
        PrayerSurah(
            id = "maun",
            title = "Mâûn Suresi",
            englishTitle = "Surah Al-Ma'un",
            arabicTitle = "سُورَةُ المَاعُون",
            category = SurahCategory.SURELER,
            whereRecited = "Namaz rekatlarında Fâtiha'dan sonra zamm-ı sure olarak okunur.",
            englishWhereRecited = "Recited after Surah Al-Fatiha in prayer rak'ahs.",
            arabicWhereRecited = "تُقرأ بعد سورة الفاتحة في ركعات الصلاة.",
            arabicText = "أَرَأَيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ ۝ فَذَلِكَ الَّذِي يَدُعُّ الْيَتِيمَ ۝ وَلَا يَحُضُّ عَلَى طَعَامِ الْمِسْكِينِ ۝ فَوَيْلٌ لِلْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَنْ صَلَاتِهِمْ سَاهُونَ ۝ الَّذِينَ هُمْ يُرَاءُونَ ۝ وَيَمْنَعُونَ الْمَاعُونَ",
            turkishPronunciation = "Era'eytellezî yükezzibü bid-dîn. Fezâlikellezî yedu'ul-yetîm. Ve lâ yehuddu alâ ta'âmil-miskîn. Feveylün lil-müsallîn. Ellezîne hüm an salâtihim sâhûn. Ellezîne hüm yürâûn. Ve yemne'ûnel-mâ'ûn.",
            turkishMeaning = "Gördün mü o hesap gününü yalanlayanı? İşte o, yetimi itip kakar; yoksulu doyurmayı teşvik etmez. Yazıklar olsun o namaz kılanlara ki, onlar namazlarından gafildirler; onlar gösteriş yaparlar ve en ufak bir yardıma bile engel olurlar.",
            englishMeaning = "Have you seen the one who denies the Recompense? For that is the one who drives away the orphan and does not encourage the feeding of the poor. So woe to those who pray, who are heedless of their prayer—those who make show of their deeds and withhold small kindnesses.",
            benefits = "İbadetin ihlasla yapılması ve yetim/yoksullara yardımı emreder.",
            englishBenefits = "Emphasizes sincerity in worship and kindness to orphans and the needy.",
            arabicBenefits = "تأمر بالإخلاص في العبادة والإحسان إلى اليتامى والمساكين.",
            audioUrl = "https://everyayah.com/data/Alafasy_128kbps/107001.mp3"
        ),
        PrayerSurah(
            id = "kevser",
            title = "Kevser Suresi",
            englishTitle = "Surah Al-Kawthar",
            arabicTitle = "سُورَةُ الكَوْثَر",
            category = SurahCategory.SURELER,
            whereRecited = "Namaz rekatlarında Fâtiha'dan sonra zamm-ı sure olarak okunur.",
            englishWhereRecited = "Recited after Surah Al-Fatiha in prayer rak'ahs.",
            arabicWhereRecited = "تُقرأ بعد سورة الفاتحة في ركعات الصلاة.",
            arabicText = "إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ ۝ إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ",
            turkishPronunciation = "İnnâ a'taynâkel-kevser. Fesalli lirabbike venhar. İnne şânieke hüvel-ebter.",
            turkishMeaning = "Şüphesiz biz sana Kevser'i verdik. Öyleyse Rabbin için namaz kıl ve kurban kes. Asıl soyu kesik olan, sana buğzeden (düşmanlık eden) kimsedir.",
            englishMeaning = "Indeed, We have granted you Al-Kawthar (abundance). So pray to your Lord and sacrifice. Indeed, your enemy is the one cut off.",
