        PrayerSurah(
            id = "kafirun",
            title = "Kâfirûn Suresi",
            englishTitle = "Surah Al-Kafirun",
            arabicTitle = "سُورَةُ الكَافِرُون",
            category = SurahCategory.SURELER,
            whereRecited = "Sabah namazının sünnetinde, tavaf namazında ve vitirde sıkça okunur.",
            englishWhereRecited = "Frequently recited in Fajr Sunnah, Tawaf prayer, and Witr prayer.",
            arabicWhereRecited = "تُقرأ كثيراً في سنة الفجر وركعتي الطواف وصلاة الوتر.",
            arabicText = "قُلْ يَا أَيُّهَا الْكَافِرُونَ ۝ لَا أَعْبُدُ مَا تَعْبُدُونَ ۝ وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ ۝ وَلَا أَنَا عَابِدٌ مَا عَبَدْتُمْ ۝ وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ ۝ لَكُمْ دِينُكُمْ وَلِيَ دِينِ",
            turkishPronunciation = "Kul yâ eyyühel-kâfirûn. Lâ a'büdü mâ ta'büdûn. Ve lâ entüm âbidûne mâ a'büd. Ve lâ ene âbidüm mâ abedtüm. Ve lâ entüm âbidûne mâ a'büd. Leküm dînüküm veliye dîn.",
            turkishMeaning = "De ki: Ey kâfirler! Ben sizin taptıklarınıza tapmam. Siz de benim taptığıma tapacak değilsiniz. Ben sizin taptıklarınıza tapacak değilim; siz de benim taptığıma tapacak değilsiniz. Sizin dininiz size, benim dinim banadır.",
            englishMeaning = "Say, 'O disbelievers, I do not worship what you worship. Nor are you worshippers of what I worship. Nor will I be a worshipper of what you worship. Nor will you be worshippers of what I worship. For you is your religion, and for me is my religion.'",
            benefits = "Şirkten uzaklaşmayı ilan eder; tevhidin en berrak ifadesidir.",
            englishBenefits = "A clear declaration of pure monotheism and disassociation from polytheism.",
            arabicBenefits = "سورة الإخلاص العملي والبراءة من الشرك.",
            audioUrl = "https://everyayah.com/data/Alafasy_128kbps/109001.mp3"
        ),
        PrayerSurah(
            id = "nasr",
            title = "Nasr Suresi",
            englishTitle = "Surah An-Nasr",
            arabicTitle = "سُورَةُ النَّصْر",
            category = SurahCategory.SURELER,
            whereRecited = "Namaz rekatlarında Fâtiha'dan sonra zamm-ı sure olarak okunur.",
            englishWhereRecited = "Recited after Surah Al-Fatiha in prayer rak'ahs.",
            arabicWhereRecited = "تُقرأ بعد سورة الفاتحة في ركعات الصلاة.",
            arabicText = "إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ۝ وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا ۝ فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا",
            turkishPronunciation = "İzâ câe nasrullâhi vel-feth. Ve raeyten-nâse yedhulûne fî dînillâhi efvâcâ. Fesebbih bi-hamdi rabbike vestağfirh, innehû kâne tevvâbâ.",
            turkishMeaning = "Allah'ın yardımı ve fetih geldiğinde, ve insanların dalga dalga Allah'ın dinine girdiklerini gördüğünde; Rabbini hamd ile tesbih et ve O'ndan bağışlanma dile. Şüphesiz O, tövbeleri çokça kabul edendir.",
